import { GROUND_Y } from "../config";
import type { LevelDef } from "./level";

/**
 * Chapter 10-2 "The Veil Crown" arena. (10-1 is generated by buildSide in
 * level.ts from its set pieces in config.ts, like every other chapter.)
 *
 * Angelo 2026-10-22 (after playing Arena V2 on his phone): the middle of
 * the arena was a pile of blocks — two stone walls, a wall-top spring and
 * the lift all sat in the central band and he "couldn't even play well".
 * REDESIGN: the floor is a clean dueling lane — NO walls, NO lift, nothing
 * standing in the middle. The vertical game lives on the edges and
 * overhead: mirrored stair balconies on both sides (low -> mid -> high)
 * and a crumbling CROWN BRIDGE that runs over the boss's head from
 * balcony to balcony, with a heart at its center. Floor springs are the
 * fast way up; every tier step is 95-120px (jump apex ~186px, spring
 * apex ~366px), and the crown-bridge gaps are a uniform 89px.
 *
 * Angelo 2026-10-23: the boss (228-248px tall) kept walking INTO the low
 * balcony blocks — the G-120/G-225 tiers cut through his body and he read
 * as stuck on them. ALL tiers moved UP: lows G-120 -> G-265, mids
 * G-225 -> G-320 (level with the highs), so the lowest platform bottom
 * clears even the Sovereign's crown by ~17px. The springs are now the
 * way up to the first tier (apex ~366px clears G-265); the tier steps
 * after that are 55px and flat hops.
 */
export function crystalCrownArena(L: LevelDef): LevelDef {
  const G = GROUND_Y;
  const x0 = 1400, x1 = x0 + 2560;
  L.width = x1 + 220;
  L.ground.push({ x0: -200, x1: x1 + 400, y: G });

  // Approach (unchanged).
  L.platforms.push(
    { x: 620, y: G - 90, prop: "plat_log" },
    { x: 980, y: G - 115, prop: "plat_medium" }
  );

  // --- Side balconies: mirrored stairs on both edges of the arena ---
  // West ascent (offsets from arena.x0). Raised 2026-10-23 (see header):
  // no tier may intersect the boss's body while he walks the lane.
  L.platforms.push(
    { x: x0 + 280, y: G - 265, prop: "plat_medium" },
    { x: x0 + 540, y: G - 320, prop: "plat_float" },
    { x: x0 + 850, y: G - 320, prop: "plat_log" }
  );
  // East ascent (mirror: 2560 - offset).
  L.platforms.push(
    { x: x0 + 2280, y: G - 265, prop: "plat_medium" },
    { x: x0 + 2020, y: G - 320, prop: "plat_float" },
    { x: x0 + 1710, y: G - 320, prop: "plat_log" }
  );

  // --- Crown bridge: the run over the boss's head, balcony to balcony ---
  // The center platform is the throne perch; the two crumbling ledges are
  // its bridges (uniform 89px gaps). Nothing hangs below it — the floor
  // underneath stays a clean fighting lane.
  L.platforms.push({ x: x0 + 1280, y: G - 335, prop: "plat_medium" });
  L.crumbles.push({ x: x0 + 1075, y: G - 335 }, { x: x0 + 1485, y: G - 335 });

  // Trampolines: one per side ascent, one per crown-bridge approach.
  // Springs never block movement — running over one is a choice to fly.
  L.springs.push(
    { x: x0 + 420, y: G },
    { x: x0 + 900, y: G },
    { x: x0 + 1660, y: G },
    { x: x0 + 2140, y: G }
  );

  L.hearts.push(
    { x: 1050, y: G - 42 },
    { x: x0 + 850, y: G - 320 - 43 },
    { x: x0 + 1280, y: G - 335 - 43 }
  );
  L.arena = { x0, x1 };
  L.portal = { x: (x0 + x1) / 2, y: G };
  return L;
}
